const j = $json;
const text = ((j.title || '') + ' ' + (j.description || '')).toLowerCase();
const frenchMarkers = ['emploi','poste','expérience','compétences','responsabilités','québec','entreprise'];
const frenchScore = frenchMarkers.reduce((acc, m) => acc + (text.includes(m) ? 1 : 0), 0);
const cv_language = frenchScore >= 2 ? 'FR' : 'EN';
return [{ json: { ...j, cv_language, cv_iterations: 0 } }];

const j = $json;
const iteration = j.cv_iterations || 0;
const previousFeedback = j.cv_optimization ? `\n\nItération précédente: optimized_ats_score=${j.cv_optimization.optimized_ats_score}, gaps_not_coverable=${JSON.stringify(j.cv_optimization.gaps_not_coverable || [])}. Améliore honnêtement la réorganisation/formulation SANS inventer de fait pour combler les gaps non couvrables.` : '';

const systemPrompt = `Tu es CV_OPTIMIZER. INTERDICTION ABSOLUE d'inventer compétence, certification, technologie, expérience, projet, entreprise, responsabilité, ou d'augmenter les années d'expérience, ou de changer un titre officiel de façon trompeuse. Tu peux réorganiser, réécrire le résumé professionnel, reformuler des tâches réelles, mettre en avant des projets réels, ajuster les mots-clés ATS pour des compétences réellement possédées, changer l'ordre des expériences. Calcule base_ats_score puis optimized_ats_score (0-100). Objectif optimized_ats_score >= ${$vars.ATS_MATCH_TARGET || 80}. Réponds UNIQUEMENT via l'outil return_cv_optimization.${previousFeedback}`;

const userMessage = JSON.stringify({
  job_offer: { title: j.title, company: j.company, description: j.description, technologies: j.technologies },
  master_cv_text: j.cv_text,
  language: j.cv_language,
  job_analysis: j.final_analysis || {},
  company_research: j.company_research || {}
});

return [{ json: { ...j, cv_iterations: iteration, optimizer_system_prompt: systemPrompt, optimizer_user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const optimization = toolUse ? toolUse.input : {};
  const job = $('Build_CV_Optimizer_Request').first().json;
  return { json: { ...job, cv_optimization: { ...optimization, model: body.model } } };
});

const j = $json;
const iterations = (j.cv_iterations || 0) + 1;
const target = parseInt($vars.ATS_MATCH_TARGET || '80', 10);
const maxIterations = parseInt($vars.CV_OPTIMIZER_MAX_ITERATIONS || '3', 10);
const targetReached = (j.cv_optimization.optimized_ats_score || 0) >= target;
const shouldRetry = !targetReached && iterations < maxIterations;
return [{ json: { ...j, cv_iterations: iterations, target_reached: targetReached, should_retry: shouldRetry } }];

const j = $json;
const systemPrompt = `Tu es un REVIEWER OpenAI spécialisé ATS. Compare le CV optimisé fourni aux mots-clés de l'offre et donne ton propre score ATS 0-100 indépendant, ainsi que les mots-clés encore manquants. Réponds UNIQUEMENT en JSON: {\"ats_score\": number, \"missing_keywords\": string[], \"notes\": string}.`;
const userMessage = JSON.stringify({ job_description: j.description, cv_sections: j.cv_optimization.cv_sections });
return [{ json: { ...j, ats_check_system_prompt: systemPrompt, ats_check_user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const job = $('Build_OpenAI_ATS_Check_Request').first().json;
  let atsCheck = {};
  try { atsCheck = JSON.parse(body.choices[0].message.content); } catch (e) { atsCheck = { ats_score: job.cv_optimization.optimized_ats_score, missing_keywords: [], notes: 'Fallback: réponse OpenAI non parsable' }; }
  return { json: { ...job, openai_ats_check: atsCheck } };
});
